solution:
def without_string(base, remove):
    if remove == "":
        return base
    lower_base = base.lower()
    lower_remove = remove.lower()
    n = len(remove)
    result = []
    i = 0
    while i < len(base):
        if lower_base[i:i+n] == lower_remove:
            i += n
        else:
            result.append(base[i])
            i += 1
    return "".join(result)

