    # your code here
    pass

solution:
def mirror_ends(s):
    n = len(s)
    for L in range(n, -1, -1):
        suffix = s[n-L:] if L > 0 else ""
        if suffix[::-1] == s[:L]:
            return s[:L]
    return ""

