    pass

solution:
def max_block(s):
    if not s:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

